      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n9/12) 경기도 거주 20~39세 청년 대상 평화.통일정책 토론회(4차)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.08. 10:07\n조회 60\n구독\n9/12) 경기도 거주 20~39세 청년 대상 평화.통일정책 토론회(4차)\n신청하신분은 재신청 안하셔도 됩니다\n만 19~39세 경기지역 거주하는 청년들을 대상으로 평화.통일 정책 토론회를 진행할 예정입니다.\n** 경기지역에 거주하는 청년 대상입니다.\n1. 조사대상 : 만 19~39세 남녀\n2. 토론회 주제 : 평화·통일 쟁점 관련 전문가 발제 및 균형 정보 학습\n인식 공유, 쟁점 탐색, 이해관 재구성 등 분임 토론 참여\n3. 토론회 일정 : 9/12(토) 13시~17시\n4. 장소 : 수원경기아트센터 도움관 2층 컨벤션홀\n5. 사례비 : 6만원 cj상품권 현장지급\n+ 2만원 모바일신세계상품권(토론회 종료 후 차주 월요일 카카오톡선물하기로 지급예정)\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n6. 신청양식 :\nhttps://kstat.surveys.kr/2026/P26051103C/index.asp?ResType=85D53C4AFCIN081\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n- 신청링크에는 토론회관련 내용과 함께 생년월일/ 성별/ 거주지역/ 이념성향/ 직업/ 신청자이름/ 연락처/ 이메일주소/ 소개자 작성으로 되어있습니다.\n(*신청링크 마지막에 소개자 입력 란이 생성되어 있습니다)\n존재하지 않는 이미지입니다.\n링크 통해 신청해주시는 분들은 순차적으로 안내 전화 드릴 예정입니다.\n** 해당 일자에 참여 가능한 신청자만 신청 & 통일에 대해 관심있는 분들만 신청 부탁드립니다..\n** 해당 토론회는 일반 소규모의 좌담회와 달리 많은 인원이 참석하는 토론회입니다.\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.08. 14:47 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n모바일패널 모집 안내\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n9/12) 경기도 거주 20~39세 청년 대상 평화.통일정책 토론회(4차)\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n고유링크) 급급급) 만50세 이상 여성) 생성형 AI 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n고유링크) 급급급) 만50세 이상 남성) 생성형 AI 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
