      "reward": "",
      "location": "",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n고유링크) 18~24세 남녀/ 25세이상 남녀 ) 생성형 AI 대규모 커뮤니티 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.08. 16:49\n조회 36\n구독\n고유링크) 18~24세 남녀/ 25세이상 남녀 ) 생성형 AI 대규모 커뮤니티 조사\nAI 커뮤니티 회원을 이번 주에는 중간 연령대도 모집 진행하기로 해서, 이번 주 금요일까지 다음과 같이 신청 요청드립니다.\nl 일별 30명\nl 연령\nn 18-24세: 15명\nn 25세 이상: 15명\n신청하신분은 재신청 안하셔도 됩니다\n6개월 이상 가능하신분만 신청해주세요~\n성 (남/여), 스마트폰 운영체제(안드로이드/iOS) 쿼터 없음\n1. 신청링크 : 해당 링크는 송난주 소개자님의 고유한 링크입니다.\n· https://kon.kric.com/project/2601012_C/INDEX.asp\n선정방법\n1) 신청링크로 1차 스크리닝 (성, 연령, 직업, 휴대폰 종류)\n2) 고객사 링크 간단한 확인 문항(10분 소요)\n3) 구글계정으로 최종 초대장 발송 -> 참여 확정\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.08. 16:57 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n<2> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 현장결제 주로 이용\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n고유링크) 18~24세 남녀/ 25세이상 남녀 ) 생성형 AI 대규모 커뮤니티 조사\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n9/14~18) 자동차 조사 대상자 모집\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n9/22~29)25~49세 여자만 가능)  금융 좌담회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
