      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n9/19~21) 26~64세 남녀) 경차 자동차 품평회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.08. 17:33\n조회 74\n구독\n9/19~21) 26~64세 남녀) 경차 자동차 품평회\n신청하신분은 재신청 안하셔도 됩니다\n모닝/레이/캐스퍼 3년이내 신차 구입자 계속 신청 부탁드릴께요~^^\n1년이내 경차구입 의향자(현재 주운전 차량은 휘발유만 가능)도 모집 인원이 많아 계속 모집하고 있어요.\n<<모집 조건>>\n보유자 : 최근 2년이내(2024년 9월 이후) 경차 모닝/레이/캐스퍼를 신차 구매한 26~64세 남녀\n의향자_1 : 차종 무관(휘발유 차량만 가능/현재 차가 없어도 가능/(중고차/렌트/리스/개인법인차 가능)하게 향후 1년이내 기존차 처분/폐차 후 /생애 첫차로 경차 구매 의향 있는 26~64세 남녀\n의향자_2 : 현재 경차 또는 중형세단 이상 또는 준중형 suv 이상 보유(휘발유 차량만 가능/중고차/렌트/리스/개인법인차 가능) 및 운전하고 있으나 향후 1년이내 세컨차 용도,신차로 경차 구매 의향 있는 26~64세 남녀\n자동차 등록증 사전 이미지 전송 必\n<<진행 일정>>\n9월 19일(토)~21일(월) 일과 중 2시간/시간은 추후 안내드립니다\n설문 진행 후 추가 좌담회 진행(선발된 명단/2시간)\n<<진행 장소>>\n서울 광진구 어린이대공원역 인근\n<<응답자 사례비>>\n보유자 8만원\n의향자 7만원\n(추가 좌담회 참석 시 5만원)\n추가 좌담회까지 참여 가능한 분으로 신청 부탁드립니다.\n<<신청양식>>\n그룹구분(보유자/의향자1~2)/이름/나이/성별/연락처/보유차종/해당차량용도(레저/하원용/출퇴근용/업무용등등)/연료유형/구입시기/신차또는중고차여부/(의향자의경우 고매고려 차종)\nhttps://forms.gle/VDtBbbvV6zM4wd1w5\n좋아요\n0\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n<4> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 카드관리 주로 이용\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n9/19~21) 26~64세 남녀) 경차 자동차 품평회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n9/14~16) 만 18-49세 대학생, 직장인, 프리랜서, 파트타이머) 스마트폰 좌담회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n<3번> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 혜택 주로 이용\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
