      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n<4> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 카드관리 주로 이용\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.08. 17:40\n조회 78\n구독\n<4> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 카드관리 주로 이용\n<내용> 안녕하세요. 신한카드 앱 SOL Pay 사용자 조사 대상자를 모집합니다.\n1) 모집대상 : (아래 항목에 모두 해당되는 분만 신청바랍니다.)\n- 최근 1개월 이내 신한 SOL Pay(쏠페이)를 사용해본 경험이 있는 분\n- 앱 개편(리뉴얼) 전에도(2026년 6월 이전) SOL Pay를 사용해본 경험이 있는 분\n'- 최근 1개월 이내 SOL Pay의 이용내역, 결제예정금액, 청구/명세서 등 카드관리 기본 기능을 위한 카드 탭을 주 4회 이상 방문하는 분이면서\n'선결제, 한도관리 등 카드관리 부가 기능을 이용해본 경험이 있는 분\n- 20~40대(만나이) 남여\n(관련업에 종사하거나 가까운 이해관계를 가진 분은 참여하실 수 없습니다.\n-> 신한카드 ·신한금융 / 카드사·은행·핀테크·간편결제사 / UX·UI·리서치)\n2) 조사 방법\n- 대면 그룹인터뷰(좌담회). 4~5명\n3) 조사 장소\n수인분당선 서울숲역 부근 (대상자 모집 후 상세 안내 예정입니다.)\n4) 조사 일정\n- 9월 21일(월) / 22일(화) 중 하루\n- 오전 10시 30분 / 오후 2시 / 오후 4시 30분\n- (1시간 30분 정도 진행될 예정이며, 1회 진행합니다. 대상자 모집 후 상세 지정 예정입니다.)\n5) 사례비\n10만원 지급 예정\n대상자로 선정되신 분께는 개별적으로 연락드릴 예정입니다.\n감사합니다.\nhttps://forms.gle/XhTCsqVVZBebE39u6\n<4> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 카드관리 주로 이용\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n부모님 케어 관련 온라인 조사\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n<4> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 카드관리 주로 이용\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n9/19~21) 26~64세 남녀) 경차 자동차 품평회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n9/14~16) 만 18-49세 대학생, 직장인, 프리랜서, 파트타이머) 스마트폰 좌담회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
