      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n부모님 케어 관련 온라인 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.08. 17:47\n조회 131\n구독\n부모님 케어 관련 온라인 조사\n조사 내용: 서울 수도권 거주 한 자녀로 (부모님도동일) 따로 거주하면서 부모님을 케어하는 자녀\n[참여 대상 자격 조건]\n구분\n주요 조건\n부모\n• 65세 이상 (거동 및 주 1회 이상 외출 가능)\n• 자녀와 따로 거주 하는 부모님\n• 가사/요리 메인 담당자\n• 삼성 스마트폰 사용\n• 스마트싱스 연결 가능 삼성 가전 2대 이상 보유\n• 삼성 헬스/맞춤형 서비스 동의자 (또는 동의 가능자)\n*삼성 워치 보유자\n자녀\n• 30~50대 남녀\n• 부모와 따로 거주\n• 삼성 스마트폰 사용 필수\n• 삼성 헬스/맞춤형 서비스 동의자 (또는 동의 가능자)\n[조사 개요(전 과정 오프라인 없음]\n1. 사전 조사: 자녀 설문(15분) → 선발된 5명 온라인 인터뷰(60분) -5만원\n2. 본 조사 (주간 과제): 조사 기간 9월 28일~12월 초\n온라인 다이어리 작성 (주 2회)\n부모/자녀 공동 과제 (주 1회)\n자녀 평가 설문 (주 1회, 10분) 부모 20만원/자녀 30만원\n3. 사후 조사: 자녀 설문(15분) + 모든 자녀/부모 그룹 좌담회(FGD) 인당 5만원\n아래 링크에 지원해 주세요.\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://naver.me/xSBHPJwD\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n2\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n9/19~21)만16세(고등학교 1학년 부터 참여 가능)~49세 미혼여성)과자 좌담회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n부모님 케어 관련 온라인 조사\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n<4> 9월 21~22일) 20~40대 남녀. 신한카드 앱 SOL Pay 사용자 그룹인터뷰 - 카드관리 주로 이용\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n9/19~21) 26~64세 남녀) 경차 자동차 품평회\n좌담회알바좌담회카페\n26.09.08.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n2\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
