      "raw_content": "영화·OTT 콘텐츠 관람자 조사-만19~44세 남녀 9/19[8만원]\n​\n대상 : 현재 만 19세 ~ 44세 남녀\n평소 영화관에서 영화를 관람하며, 1년에 최소 2번 이상 영화관에서 영화를 관람하는 사람\n향후 6개월 이내에 영화관에서 영화를 볼 의향이 있는 사람\n할리우드 영화를 영화관에서 주로 보는 사람\n슈퍼히어로 영화를 좋아하거나 적어도 거부하지 않는 사람\n아래 작품들 중 극장 개봉작을 영화관에서 보고, OTT시리즈를 OTT로 본 적 있는 사람\n[극장 개봉작]\n스파이더맨: 브랜드 뉴 데이 (2026)\n썬더볼츠 (2025)\n판타스틱 4: 퍼스트 스텝 (2025)\n캡틴 아메리카: 브레이브 뉴 월드 (2025)\n데드풀과 울버린 (2024)\n더 마블스 (2023)\n가디언즈 오브 갤럭시: Volume 3 (2023)\n앤트맨과 와스프: 퀀텀매니아 (2023)\n블랙 팬서: 와칸다 포에버 (2022)\n토르: 러브 앤 썬더 (2022)\n닥터 스트레인지: 대혼돈의 멀티버스 (2022)\n스파이더맨: 노 웨이 홈 (2021)\n샹치와 텐 링즈의 전설 (2021)\n이터널스 (2021)\n블랙 위도우 (2021)\n슈퍼걸 (2026)\n슈퍼맨 (2025)\n베놈: 라스트 댄스 (2024)\n원더 우먼 1984 (2020)\n더 배트맨 (2022)\n플래시 (2023)\n어벤져스: 엔드게임 (2019)\n캡틴 마블 (2019)\n캡틴 아메리카: 시빌 워 (2016)\n판타스틱 4 (2015)\n​\n[OTT 시리즈]\n아이언하트\n퍼니셔\n원더맨\n로키\n시크릿 인베이젼\n미즈 마블\n문나이트\n호크아이\n완다비전\n데어데블: 본 어게인\n왓 이프...\n팔콘과 윈터 솔저\n아가사 올 어롱\n일정 : 9월 19일(토) 오후 1시, 3시 30분, 5시 30분, 7시 30분 타임 중 한번만 참여\n방법 : 좌담회\n소요시간 : 80분\n사례비 : 좌담회 참여 후 현금 8만원 지급\n장소 : 강남구 신사동\n대상 선정 절차\n신청하신 내용을 검토해서 조건에 맞는 경우 문자로 조사대상 확인을 위한 질문 링크 발송합니다.\n링크에 응답하시면 내용 확인 후 조건에 맞는 분들에 한해 전화로 한번 더 확인 후 최종 확정하는 절차로 진행됩니다.\n​\n신청하기",
